// filled by applyStory(): every step in order, and where each quest sits in the story
export const MSQ_ORDER = [];
export const MSQ_AT = {};

export function applyStory(QUESTS, NPCS) {
  const npc = (id) => NPCS.find((n) => n.id === id);
  for (const [id, Q] of Object.entries(STORY_QUESTS)) { QUESTS[id] = Q; const g = npc(Q.giver); if (g) (g.quests ||= []).push(id); }
  for (const [qid, to] of STORY_MOVES) {
    const Q = QUESTS[qid];
    if (!Q) continue;
    const from = npc(Q.giver);
    if (from?.quests) from.quests = from.quests.filter((q) => q !== qid);
    Q.giver = to;
    const g = npc(to); if (g && !(g.quests ||= []).includes(qid)) g.quests.push(qid);
  }
  for (const [qid, t] of Object.entries(STORY_TEXT)) if (QUESTS[qid]) QUESTS[qid].text = t;
  for (const [qid, t] of Object.entries(STORY_DONE)) if (QUESTS[qid]) QUESTS[qid].done = t;
  for (const [qid, t] of Object.entries(STORY_SCENES)) if (QUESTS[qid]) QUESTS[qid].scene = t;
  STORY.forEach((C, ci) => C.steps.forEach(([qid, recap], si) => {
    const Q = QUESTS[qid];
    if (!Q) return;
    const n = MSQ_ORDER.length;
    // the chain: each step needs the one before it, whatever the quest asked for on its own
    if (n > 0) Q.pre = MSQ_ORDER[n - 1]; else delete Q.pre;
    Q.msq = { ch: ci, step: si, n, first: si === 0, last: si === C.steps.length - 1 };
    Q.recap = recap;
    MSQ_ORDER.push(qid);
    MSQ_AT[qid] = Q.msq;
  }));
  for (const C of STORY) { const lv = C.steps.map(([q]) => QUESTS[q]?.lvl || 1); C.lvl = [Math.min(...lv), Math.max(...lv)]; }
}

// where a player stands in the story: the step after the furthest one done (old characters may have gaps behind it;
// those steps stay open as missed steps). Returns { n, qid, ch, step } or { n, end: true } once all is done.
export function storyAt(done = {}) {
  let n = 0;
  for (let i = MSQ_ORDER.length - 1; i >= 0; i--) if (done[MSQ_ORDER[i]]) { n = i + 1; break; }
  if (n >= MSQ_ORDER.length) return { n, end: true, ch: STORY.length - 1 };
  const qid = MSQ_ORDER[n];
  return { n, qid, ch: MSQ_AT[qid].ch, step: MSQ_AT[qid].step };
}
